"""Semantic boundaries on the six selected source sheets, in 600x760 coordinates."""
from PIL import Image, ImageDraw, ImageChops
import numpy as np
SIZE=(1200,1520)
def poly(p):
 im=Image.new('L',SIZE);ImageDraw.Draw(im).polygon([(round(x*2),round(y*2)) for x,y in p],fill=255);return im
def rect(b):
 x,y,r,d=b;return poly([(x,y),(r,y),(r,d),(x,d)])
def ell(b):
 im=Image.new('L',SIZE);ImageDraw.Draw(im).ellipse(tuple(round(v*2) for v in b),fill=255);return im
def union(*a):
 im=Image.new('L',SIZE)
 for x in a:im=ImageChops.lighter(im,x)
 return im
def circles(a):return union(*[ell((x-r,y-r,x+r,y+r)) for x,y,r in a])
def line(p,w):
 im=Image.new('L',SIZE);ImageDraw.Draw(im).line([(round(x*2),round(y*2))for x,y in p],fill=255,width=round(w*2),joint='curve');return im
